#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    int countStudents(vector<int>& students, vector<int>& sandwiches) {
        queue<int> q;
        for (int s : students) q.push(s);

        int i = 0, tries = 0;
        while (!q.empty() && tries < q.size()) {
            if (q.front() == sandwiches[i]) {
                q.pop();
                i++;
                tries = 0;
            } else {
                q.push(q.front());
                q.pop();
                tries++;
            }
        }
        return q.size();
    }
};
